"""Browser tools for a model-driven agent: observe a page as text plus numbered controls, act on them by number.

Nothing here knows any website. The model picks every target; code only turns pages into text and executes clicks.
"""
import io
import re
import zipfile

TAG_JS = """
(start) => {
  document.querySelectorAll('[data-aid]').forEach(e => e.removeAttribute('data-aid'));
  const sel = 'a[href],button,input,select,textarea,summary,[role=button],[role=link],[role=tab],[role=menuitem],[role=option],[onclick]';
  const out = []; let n = start;
  for (const el of document.querySelectorAll(sel)) {
    const r = el.getBoundingClientRect(); const st = getComputedStyle(el);
    if (st.visibility === 'hidden' || st.display === 'none' || (r.width === 0 && r.height === 0)) continue;
    if (el.tagName === 'INPUT' && el.type === 'hidden') continue;
    el.setAttribute('data-aid', String(n));
    const tag = el.tagName.toLowerCase();
    let label = (el.innerText || el.getAttribute('aria-label') || el.placeholder || el.title || '').trim().replace(/\\s+/g, ' ').slice(0, 90);
    if (tag === 'input' || tag === 'select' || tag === 'textarea') {
      const l = el.labels && el.labels[0] ? el.labels[0].innerText.trim().replace(/\\s+/g, ' ') : '';
      label = l || el.getAttribute('aria-label') || el.placeholder || el.name || el.id || label;
      if (el.type === 'submit' || el.type === 'button') label = el.value || label;
    }
    const item = {id: n, tag, type: el.type || '', label: String(label).slice(0, 90), href: (el.getAttribute('href') || '').slice(0, 140),
                  name: el.name || '', disabled: !!el.disabled};
    if (tag === 'input' || tag === 'textarea') item.value = el.type === 'password' ? '' : String(el.value || '').slice(0, 60);
    if (el.type === 'checkbox' || el.type === 'radio') item.checked = el.checked;
    if (tag === 'select') {
      item.options = [...el.options].map(o => o.text.trim().replace(/\\s+/g, ' ').slice(0, 60)).slice(0, 40);
      item.value = el.options[el.selectedIndex] ? el.options[el.selectedIndex].text.trim() : '';
    }
    out.push(item); n++;
  }
  return out;
}
"""


def _squash(text: str) -> str:
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    return re.sub(r"\n\s*\n+", "\n", text).strip()


class Session:
    """One browser: the current page, the numbered controls of its last observation, and its tabs."""

    def __init__(self, page, name: str = ""):
        self.page = page
        self.name = name
        self.elements: dict[int, tuple] = {}
        page.context.on("page", self._new_page)
        page.on("dialog", self._dialog)
        self.dialogs: list[str] = []

    def _new_page(self, page):
        page.on("dialog", self._dialog)

    async def _dialog(self, dialog):
        self.dialogs.append(f"{dialog.type}: {dialog.message}")
        try:
            await dialog.accept()
        except Exception:
            pass

    async def _settle(self):
        try:
            await self.page.wait_for_load_state("domcontentloaded", timeout=6000)
        except Exception:
            pass
        try:
            await self.page.wait_for_load_state("networkidle", timeout=2500)
        except Exception:
            pass

    async def observe(self, text_chars: int = 5000, text_offset: int = 0, max_elements: int = 120) -> str:
        page = self.page
        await self._settle()
        self.elements = {}
        parts, items, counter = [], [], 0
        frames = [page.main_frame] + [f for f in page.frames if f != page.main_frame]
        for index, frame in enumerate(frames):
            try:
                found = await frame.evaluate(TAG_JS, counter)
                text = await frame.evaluate("document.body ? document.body.innerText : ''")
            except Exception:
                continue
            for item in found:
                self.elements[item["id"]] = (frame, f'[data-aid="{item["id"]}"]')
                item["frame"] = index
                items.append(item)
            counter += len(found)
            text = _squash(text or "")
            if text:
                parts.append(text if index == 0 else f"[iframe {frame.url}]\n{text}")
        body = "\n".join(parts)
        total = len(body)
        shown = body[text_offset:text_offset + text_chars]
        try:
            title = await page.title()
        except Exception:
            title = ""
        lines = [f"URL: {page.url}", f"TITLE: {title}", f"TABS: {len(page.context.pages)}"]
        if self.dialogs:
            lines.append("DIALOGS SEEN: " + " | ".join(self.dialogs[-3:]))
            self.dialogs.clear()
        lines.append(f"--- PAGE TEXT (chars {text_offset}-{text_offset + len(shown)} of {total}) ---")
        lines.append(shown)
        if text_offset + len(shown) < total:
            lines.append(f"[more text: call observe with text_offset={text_offset + len(shown)}]")
        lines.append("--- CONTROLS ---")
        for item in items[:max_elements]:
            bits = [f"[{item['id']}]", item["tag"] if not item["type"] else f"{item['tag']}:{item['type']}", repr(item["label"])]
            if item.get("href"):
                bits.append("href=" + item["href"])
            if item.get("name"):
                bits.append("name=" + item["name"])
            if "value" in item and item["value"]:
                bits.append("value=" + repr(item["value"]))
            if item.get("checked"):
                bits.append("CHECKED")
            if item.get("disabled"):
                bits.append("DISABLED")
            if item.get("options"):
                bits.append("options=" + " | ".join(item["options"]))
            lines.append(" ".join(bits))
        if len(items) > max_elements:
            lines.append(f"[{len(items) - max_elements} more controls not shown]")
        return "\n".join(lines)

    def _target(self, element_id: int):
        entry = self.elements.get(int(element_id))
        if not entry:
            raise ValueError(f"No control [{element_id}] on the last observation; call observe first.")
        frame, selector = entry
        return frame.locator(selector).first

    async def goto(self, url: str) -> str:
        await self.page.goto(url, wait_until="domcontentloaded", timeout=30000)
        return await self.observe()

    async def click(self, element_id: int) -> str:
        context = self.page.context
        before = len(context.pages)
        await self._target(element_id).click(timeout=8000)
        await self.page.wait_for_timeout(400)
        if len(context.pages) > before:
            self.page = context.pages[-1]
        return await self.observe()

    async def fill(self, element_id: int, text: str) -> str:
        await self._target(element_id).fill(text, timeout=8000)
        return f"filled [{element_id}]"

    async def select(self, element_id: int, option: str) -> str:
        target = self._target(element_id)
        try:
            await target.select_option(label=option, timeout=6000)
        except Exception:
            await target.select_option(value=option, timeout=6000)
        return f"selected {option!r} in [{element_id}]"

    async def check(self, element_id: int, checked: bool = True) -> str:
        await self._target(element_id).set_checked(bool(checked), timeout=6000)
        return f"[{element_id}] checked={checked}"

    async def press(self, key: str) -> str:
        await self.page.keyboard.press(key)
        await self.page.wait_for_timeout(400)
        return await self.observe()

    async def back(self) -> str:
        await self.page.go_back(wait_until="domcontentloaded", timeout=20000)
        return await self.observe()

    async def switch_tab(self, index: int) -> str:
        pages = self.page.context.pages
        self.page = pages[int(index)]
        await self.page.bring_to_front()
        return await self.observe()

    async def read_url(self, url: str, max_chars: int = 9000, offset: int = 0) -> str:
        """Fetch a document with this browser's cookies and return its text (HTML, PDF, ZIP, plain)."""
        response = await self.page.context.request.get(url, timeout=30000)
        data = await response.body()
        kind = (response.headers.get("content-type") or "").lower()
        return f"[{response.status} {kind}]\n" + describe_bytes(data, kind, url)[offset:offset + max_chars]


def describe_bytes(data: bytes, kind: str, name: str = "") -> str:
    lowered = (name or "").lower()
    if "pdf" in kind or lowered.endswith(".pdf") or data[:4] == b"%PDF":
        try:
            from pypdf import PdfReader
            reader = PdfReader(io.BytesIO(data))
            return _squash("\n".join(f"[page {i + 1}]\n" + (p.extract_text() or "") for i, p in enumerate(reader.pages)))
        except Exception as error:
            return f"(unreadable PDF: {error})"
    if "zip" in kind or lowered.endswith(".zip") or data[:2] == b"PK":
        try:
            archive = zipfile.ZipFile(io.BytesIO(data))
            out = []
            for info in archive.infolist():
                if info.is_dir():
                    continue
                member = archive.read(info.filename)
                out.append(f"=== {info.filename} ({info.file_size} bytes)\n" + describe_bytes(member, "", info.filename)[:6000])
            return "\n".join(out)
        except Exception as error:
            return f"(unreadable ZIP: {error})"
    text = data.decode("utf-8", errors="replace")
    if "html" in kind or text.lstrip().lower().startswith(("<!doctype", "<html")):
        text = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", "", text)
        text = re.sub(r"<[^>]+>", "\n", text)
    return _squash(text)

"""A small tool-calling loop over the hosted Qwen, plus the arithmetic helper agents use for money."""
import ast
import json
import math
import os
import time
from decimal import ROUND_HALF_UP, Decimal

import models

MODEL = os.environ.get("QWEN_MODEL", models.QWEN_MODEL)
KEEP_FULL = 5          # tool results kept in full; older ones are shortened
OLD_RESULT_CHARS = 300


def tool(name: str, description: str, properties: dict | None = None, required: list[str] | None = None) -> dict:
    return {"type": "function", "function": {"name": name, "description": description, "parameters": {
        "type": "object", "properties": properties or {}, "required": required or []}}}


STR = {"type": "string"}
INT = {"type": "integer"}
NUM = {"type": "number"}


def _shorten_old(messages: list[dict]) -> None:
    tool_idx = [i for i, m in enumerate(messages) if m.get("role") == "tool"]
    for i in tool_idx[:-KEEP_FULL]:
        content = messages[i]["content"]
        if len(content) > OLD_RESULT_CHARS:
            messages[i]["content"] = content[:OLD_RESULT_CHARS] + " …[older result shortened; re-observe if needed]"


async def run_agent(name: str, system: str, task: str, tools: list[dict], handlers: dict, deadline: float,
                    max_steps: int = 80, log=print) -> str:
    """Drive the model until it calls `finish`, stops calling tools, runs out of steps, or hits the deadline."""
    client = models.qwen()
    messages = [{"role": "system", "content": system}, {"role": "user", "content": task}]
    nudges = 0
    for step in range(max_steps):
        if time.time() > deadline:
            log(f"[{name}] deadline reached at step {step}")
            return "deadline"
        _shorten_old(messages)
        try:
            reply = await client.chat.completions.create(
                model=MODEL, messages=messages, tools=tools, tool_choice="auto", temperature=0.2)
        except Exception as error:  # a flaky call: back off and retry within the same budget
            log(f"[{name}] model error: {error!r}")
            await _sleep(3)
            continue
        message = reply.choices[0].message
        entry = {"role": "assistant", "content": message.content or ""}
        if message.tool_calls:
            entry["tool_calls"] = [{"id": c.id, "type": "function",
                                    "function": {"name": c.function.name, "arguments": c.function.arguments or "{}"}}
                                   for c in message.tool_calls]
        messages.append(entry)
        if not message.tool_calls:
            nudges += 1
            if nudges > 2:
                return message.content or "stopped"
            messages.append({"role": "user", "content": "Continue by calling a tool. When you are completely done, call `finish`."})
            continue
        for call in message.tool_calls:
            fname = call.function.name
            try:
                args = json.loads(call.function.arguments or "{}")
            except ValueError:
                args = {}
            handler = handlers.get(fname)
            if handler is None:
                result = f"Unknown tool {fname}."
            else:
                try:
                    result = await handler(**args)
                except Exception as error:
                    result = f"ERROR: {type(error).__name__}: {str(error)[:400]}"
            log(f"[{name}] {fname}({json.dumps(args, ensure_ascii=False)[:140]}) -> {str(result)[:90]!r}")
            if fname == "finish":
                return str(args.get("summary", ""))
            messages.append({"role": "tool", "tool_call_id": call.id, "content": str(result)})
    return "max steps"


async def _sleep(seconds: float):
    import asyncio
    await asyncio.sleep(seconds)


# --- arithmetic: exact decimals with half-up rounding, no model guesswork --------------------------------------------

def round_half_up(value, places: int = 2) -> Decimal:
    quantum = Decimal(1).scaleb(-places)
    return Decimal(value).quantize(quantum, rounding=ROUND_HALF_UP)


class _Decimalize(ast.NodeTransformer):
    def visit_Constant(self, node):
        if isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
            return ast.copy_location(ast.Call(ast.Name("D", ast.Load()), [ast.Constant(str(node.value))], []), node)
        return node


_ALLOWED = (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Call, ast.Name, ast.Load, ast.Constant, ast.Add, ast.Sub,
            ast.Mult, ast.Div, ast.USub, ast.UAdd, ast.Pow, ast.Mod, ast.List, ast.Tuple, ast.Compare, ast.Lt, ast.LtE,
            ast.Gt, ast.GtE, ast.Eq, ast.NotEq, ast.IfExp, ast.keyword, ast.Starred)
_FUNCS = {"D": Decimal, "round_half_up": round_half_up, "ceil": lambda x: Decimal(math.ceil(Decimal(x))),
          "floor": lambda x: Decimal(math.floor(Decimal(x))), "min": min, "max": max,
          "sum": lambda *a: sum((Decimal(x) for x in (a[0] if len(a) == 1 and isinstance(a[0], (list, tuple)) else a)), Decimal(0))}


def calculate(expression: str) -> str:
    """Evaluate an arithmetic expression with exact decimals. Numbers are decimals; use round_half_up(x, 2)."""
    tree = ast.parse(expression.strip(), mode="eval")
    for node in ast.walk(tree):
        if not isinstance(node, _ALLOWED):
            raise ValueError(f"not allowed in a calculation: {type(node).__name__}")
        if isinstance(node, ast.Name) and node.id not in _FUNCS:
            raise ValueError(f"unknown name {node.id}")
    tree = ast.fix_missing_locations(_Decimalize().visit(tree))
    value = eval(compile(tree, "<calc>", "eval"), {"__builtins__": {}}, dict(_FUNCS))
    return str(value)
